import pandas as pd


def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine high watermark timestamp (events with ts <= high_ts are already applied)
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Only events strictly after the watermark need to be applied
    if high_ts is not None:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        events = cdc_events.copy()

    # Sequential application requires deterministic ordering per item:
    # by event_ts ascending, then event_seq ascending as tie-break.
    events = events.sort_values(["item_id", "event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"],
            "exists": True,
        }

    for _, ev in events.iterrows():
        item = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        ts = ev["event_ts"]

        if item not in state:
            state[item] = {"qty_on_hand": 0, "last_event_ts": None, "exists": False}

        s = state[item]

        if op == "R":
            if not s["exists"]:
                s["qty_on_hand"] = 0
            s["qty_on_hand"] = s["qty_on_hand"] + qty
            s["exists"] = True
            s["last_event_ts"] = ts
        elif op == "A":
            s["qty_on_hand"] = qty
            s["exists"] = True
            s["last_event_ts"] = ts
        elif op == "D":
            s["exists"] = False
            s["qty_on_hand"] = 0
            s["last_event_ts"] = ts

        state[item] = s

    rows = []
    for item, s in state.items():
        if s["exists"]:
            rows.append(
                {
                    "item_id": item,
                    "qty_on_hand": s["qty_on_hand"],
                    "last_event_ts": s["last_event_ts"],
                }
            )

    new_snapshot = pd.DataFrame(rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    return {"new_snapshot": new_snapshot}
